//! 📦️ Typed PLY snapshot records retain scalar words, list order and declaration metadata.
use semio_framework_value::ValueError;
use semio_framework_value::ValueRefusalKind;
use crate::standards::v1_0::subsets::any::schema::snapshot::{PlySnapshot,PlyFormat,PlyElement,PlyProperty,PlyRow,PlyValue,PlyScalarType};
fn scalar_name(kind:PlyScalarType)->&'static str{match kind{PlyScalarType::Char=>"char",PlyScalarType::UChar=>"uchar",PlyScalarType::Short=>"short",PlyScalarType::UShort=>"ushort",PlyScalarType::Int=>"int",PlyScalarType::UInt=>"uint",PlyScalarType::Float=>"float",PlyScalarType::Double=>"double"}}
fn scalar_kind(value:&str)->Result<PlyScalarType,ValueError>{match value{"char"=>Ok(PlyScalarType::Char),"uchar"=>Ok(PlyScalarType::UChar),"short"=>Ok(PlyScalarType::Short),"ushort"=>Ok(PlyScalarType::UShort),"int"=>Ok(PlyScalarType::Int),"uint"=>Ok(PlyScalarType::UInt),"float"=>Ok(PlyScalarType::Float),"double"=>Ok(PlyScalarType::Double),_=>Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY snapshot scalar kind is unknown"))}}
#[derive(semio_framework_dsl_record_derive::DslRecord)]
pub(crate) struct Value{kind:String,integer_value:Option<i64>,float32_ieee754_bits:Option<u32>,float64_ieee754_bits:Option<u64>,list_values:Vec<u64>}
impl Value{fn scalar(value:&PlyValue)->Self{let mut result=Self{kind:String::new(),integer_value:None,float32_ieee754_bits:None,float64_ieee754_bits:None,list_values:Vec::new()};match value{PlyValue::Char(value)=>{result.kind="char".into();result.integer_value=Some(i64::from(*value))},PlyValue::UChar(value)=>{result.kind="uchar".into();result.integer_value=Some(i64::from(*value))},PlyValue::Short(value)=>{result.kind="short".into();result.integer_value=Some(i64::from(*value))},PlyValue::UShort(value)=>{result.kind="ushort".into();result.integer_value=Some(i64::from(*value))},PlyValue::Int(value)=>{result.kind="int".into();result.integer_value=Some(i64::from(*value))},PlyValue::UInt(value)=>{result.kind="uint".into();result.integer_value=Some(i64::from(*value))},PlyValue::Float(value)=>{result.kind="float".into();result.float32_ieee754_bits=Some(value.to_bits())},PlyValue::Double(value)=>{result.kind="double".into();result.float64_ieee754_bits=Some(value.to_bits())},PlyValue::List(_)=>result.kind="list".into()}result}}
fn primitive(value:Value)->Result<PlyValue,ValueError>{if !value.list_values.is_empty()||usize::from(value.integer_value.is_some())+usize::from(value.float32_ieee754_bits.is_some())+usize::from(value.float64_ieee754_bits.is_some())!=1{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY native scalar payload differs"))}let integer=||value.integer_value.ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY native integer missing"));match value.kind.as_str(){"char"=>i8::try_from(integer()?).map(PlyValue::Char).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e.to_string())),"uchar"=>u8::try_from(integer()?).map(PlyValue::UChar).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e.to_string())),"short"=>i16::try_from(integer()?).map(PlyValue::Short).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e.to_string())),"ushort"=>u16::try_from(integer()?).map(PlyValue::UShort).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e.to_string())),"int"=>i32::try_from(integer()?).map(PlyValue::Int).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e.to_string())),"uint"=>u32::try_from(integer()?).map(PlyValue::UInt).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e.to_string())),"float"=>Ok(PlyValue::Float(f32::from_bits(value.float32_ieee754_bits.ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY binary32 missing"))?))),"double"=>Ok(PlyValue::Double(f64::from_bits(value.float64_ieee754_bits.ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY binary64 missing"))?))),_=>Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY native scalar kind differs"))}}
#[derive(semio_framework_dsl_record_derive::DslRecord)]
pub(crate) struct Property{name:String,form:String,scalar_kind:Option<String>,count_kind:Option<String>,value_kind:Option<String>}
impl From<&PlyProperty> for Property{fn from(value:&PlyProperty)->Self{match value{PlyProperty::Scalar{name,kind}=>Self{name:name.clone(),form:"scalar".into(),scalar_kind:Some(scalar_name(*kind).into()),count_kind:None,value_kind:None},PlyProperty::List{name,count_kind,value_kind}=>Self{name:name.clone(),form:"list".into(),scalar_kind:None,count_kind:Some(scalar_name(*count_kind).into()),value_kind:Some(scalar_name(*value_kind).into())}}}}
impl TryFrom<Property> for PlyProperty{type Error=ValueError;fn try_from(value:Property)->Result<Self,ValueError>{match value.form.as_str(){"scalar" if value.count_kind.is_none()&&value.value_kind.is_none()=>Ok(Self::Scalar{name:value.name,kind:scalar_kind(value.scalar_kind.as_deref().ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY scalar declaration kind missing"))?)?}),"list" if value.scalar_kind.is_none()=>Ok(Self::List{name:value.name,count_kind:scalar_kind(value.count_kind.as_deref().ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY list count kind missing"))?)?,value_kind:scalar_kind(value.value_kind.as_deref().ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY list value kind missing"))?)?}),_=>Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY snapshot property form and typed fields differ"))}}}
#[derive(semio_framework_dsl_record_derive::DslRecord)]
pub(crate) struct Row{values:Vec<u64>}
#[derive(semio_framework_dsl_record_derive::DslRecord)]
pub(crate) struct Element{name:String,count:u64,properties:Vec<Property>,rows:Vec<Row>}
#[derive(semio_framework_dsl_record_derive::DslRecord)]
pub(crate) struct Snapshot{schema:String,format:String,comments:Vec<String>,elements:Vec<Element>,values:Vec<Value>}
impl From<&PlySnapshot> for Snapshot{fn from(value:&PlySnapshot)->Self{let mut pending=Vec::new();let mut elements=Vec::new();for element in&value.elements{let mut rows=Vec::new();for row in&element.rows{let mut values=Vec::new();for value in&row.values{values.push(pending.len()as u64);pending.push(value);}rows.push(Row{values});}elements.push(Element{name:element.name.clone(),count:element.count,properties:element.properties.iter().map(Property::from).collect(),rows});}let mut values=Vec::new();let mut index=0;while index<pending.len(){let value=pending[index];let mut node=Value::scalar(value);if let PlyValue::List(items)=value{for value in items{node.list_values.push(pending.len()as u64);pending.push(value);}}values.push(node);index+=1;}Self{schema:value.schema.clone(),format:match value.format{PlyFormat::Ascii=>"ascii",PlyFormat::BinaryLittleEndian=>"binaryLittleEndian",PlyFormat::BinaryBigEndian=>"binaryBigEndian"}.into(),comments:value.comments.clone(),elements,values}}}
pub(crate) struct Values(Vec<Option<PlyValue>>);
impl Drop for Values{fn drop(&mut self){for value in self.0.iter_mut().filter_map(Option::take){retire_value(value)}}}
pub(crate) struct Items(Vec<PlyValue>);
impl Drop for Items{fn drop(&mut self){for value in self.0.drain(..){retire_value(value)}}}
fn take(values:&mut Values,id:u64,parent:Option<usize>)->Result<PlyValue,ValueError>{let id=usize::try_from(id).map_err(|_|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native index exceeds native width"))?;if id>=values.0.len()||parent.is_some_and(|parent|id<=parent){return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY native topology differs"))}values.0[id].take().ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY native repeated value ownership"))}
fn reconstruct(value:Snapshot,control:&mut semio_framework_value::NativeDecodeControl<'_>)->Result<PlySnapshot,ValueError>{
 let Snapshot{schema,format,comments,elements,values}=value;let format=match format.as_str(){"ascii"=>PlyFormat::Ascii,"binaryLittleEndian"=>PlyFormat::BinaryLittleEndian,"binaryBigEndian"=>PlyFormat::BinaryBigEndian,_=>return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY native format differs"))};
 let mut units=values.len();control.begin_stage(values.len())?;for value in&values{control.step()?;units=units.checked_add(value.list_values.len()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native work overflow"))?;}control.begin_stage(units)?;
 let mut forest=Values(control.allocate_vec::<Option<PlyValue>>(values.len())?);forest.0.resize_with(values.len(),||None);
 for(index,value)in values.into_iter().enumerate().rev(){control.step()?;let value=if value.kind=="list"{if value.integer_value.is_some()||value.float32_ieee754_bits.is_some()||value.float64_ieee754_bits.is_some(){return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY native list has scalar fields"))}let mut children=Items(control.allocate_vec::<PlyValue>(value.list_values.len())?);for id in value.list_values{control.step()?;children.0.push(take(&mut forest,id,Some(index))?);}PlyValue::List(std::mem::take(&mut children.0))}else{primitive(value)?};forest.0[index]=Some(value);}
 let mut units=elements.len();control.begin_stage(elements.len())?;for element in&elements{control.step()?;units=units.checked_add(element.properties.len()).and_then(|n|n.checked_add(element.rows.len())).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native work overflow"))?;control.scoped_stage(|control|->Result<(),ValueError>{control.begin_stage(element.rows.len())?;for row in&element.rows{control.step()?;units=units.checked_add(row.values.len()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native work overflow"))?;}Ok(())})?;}control.begin_stage(units)?;
 let mut snapshot=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(PlySnapshot{schema,format,comments,elements:control.allocate_vec::<PlyElement>(elements.len())?},retire);
 for element in elements{control.step()?;let mut decoded=PlyElement{name:element.name,count:element.count,properties:control.allocate_vec::<PlyProperty>(element.properties.len())?,rows:control.allocate_vec::<PlyRow>(element.rows.len())?};for property in element.properties{control.step()?;decoded.properties.push(PlyProperty::try_from(property)?);}let mut decoded=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(decoded,|element:PlyElement|{for row in element.rows{for value in row.values{retire_value(value)}}});for row in element.rows{control.step()?;let mut owned=Items(control.allocate_vec::<PlyValue>(row.values.len())?);for id in row.values{control.step()?;owned.0.push(take(&mut forest,id,None)?);}decoded.as_mut().rows.push(PlyRow{values:std::mem::take(&mut owned.0)});}snapshot.as_mut().elements.push(decoded.take());}
 if forest.0.iter().any(Option::is_some){return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY native unowned values"))}control.checkpoint()?;Ok(snapshot.take())
}
impl TryFrom<Snapshot> for PlySnapshot{type Error=String;fn try_from(value:Snapshot)->Result<Self,String>{reconstruct(value,&mut semio_framework_value::NativeDecodeControl::new(usize::MAX,&mut |_|true)).map_err(semio_framework_value::ValueError::into_message)}}

impl store::ArtifactPack for PlySnapshot{
 fn sqlite_snapshot_codec()->Option<store::ArtifactSqliteSnapshotCodec>{Some(<Self as store::ArtifactSqliteSnapshot>::sqlite_codec())}
 fn encode_pack_with(&self,options:&store::PackEncodeOptions)->Result<Vec<u8>,store::PackError>{let snapshot=Snapshot::from(self);let inner=store::pack_rt::encode_document(&Snapshot::__dsl_spec(),&snapshot.__dsl_to_record(),options)?;let envelope=store::semio_format::SemioEnvelope::from_envelope_id("stdio.ply",store::semio_format::Component::Pack,1).map_err(|error|store::PackError::from(error.into_value_error()))?;Ok(store::semio_format::wrap_binary(&envelope,&inner))}
 fn decode_pack_with(bytes:&[u8],options:&store::PackDecodeOptions)->Result<Self,store::PackError>{let(envelope,inner)=store::semio_format::unwrap_binary(bytes).map_err(|error|store::PackError::from(error.into_value_error()))?;if !envelope.matches_identity("stdio.ply",store::semio_format::Component::Pack,1){return Err(store::PackError::from(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "PLY snapshot pack identity differs")));}let(record,_)=store::pack_rt::decode_document(&inner,&Snapshot::__dsl_spec(),options)?;Self::try_from(Snapshot::__dsl_from_record(&record).map_err(store::text_error_to_pack_error)?).map_err(|detail| store::PackError::from(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, detail)))}
 fn record_spec()->Option<semio_framework_dsl_record::RecordSpec>{Some(Snapshot::__dsl_spec())}
}

pub(crate) fn retire_value(value:PlyValue){let mut pending=vec![value];while let Some(value)=pending.pop(){if let PlyValue::List(values)=value{pending.extend(values);}}}
pub(crate) fn retire(value:PlySnapshot){for element in value.elements{for row in element.rows{for value in row.values{retire_value(value);}}}}

pub(crate)fn spec()->semio_framework_dsl_record::RecordSpec{Snapshot::__dsl_spec()}
pub(crate)fn spec_producer()->semio_framework_dsl_record::RecordSpecProducer{Snapshot::__dsl_spec_producer()}
pub(crate)fn reconstruct_record_controlled(source:&semio_framework_dsl_record::RecordValue,control:&mut semio_framework_value::NativeDecodeControl<'_>,maximum_rows:usize)->Result<PlySnapshot,ValueError>{
 fn list(source:&semio_framework_dsl_record::RecordValue,id:u16)->Result<&[semio_framework_dsl_record::FieldValue],ValueError>{match source.fields.get(&id){Some(semio_framework_dsl_record::FieldValue::List(values))=>Ok(values),_=>Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY native list field differs"))}}
 fn record(value:&semio_framework_dsl_record::FieldValue)->Result<&semio_framework_dsl_record::RecordValue,ValueError>{match value{semio_framework_dsl_record::FieldValue::Record(value)=>Ok(value),_=>Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"PLY native typed record differs"))}}
 control.scoped_stage(|control|->Result<(),ValueError>{let elements=list(source,3)?;let values=list(source,4)?;let mut rows=1usize.checked_add(list(source,2)?.len()).and_then(|n|n.checked_add(elements.len())).and_then(|n|n.checked_add(values.len())).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native row count overflow"))?;let check=|rows:usize|if rows>maximum_rows{Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::OwnershipLimit,"PLY native row limit"))}else{Ok(())};check(rows)?;
 control.begin_stage(elements.len()+values.len())?;for value in elements{control.step()?;let element=record(value)?;let occurrences=list(element,3)?;rows=rows.checked_add(list(element,2)?.len()).and_then(|n|n.checked_add(occurrences.len())).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native row count overflow"))?;check(rows)?;control.scoped_stage(|control|->Result<(),ValueError>{control.begin_stage(occurrences.len())?;for row in occurrences{control.step()?;rows=rows.checked_add(list(record(row)?,0)?.len()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native row count overflow"))?;check(rows)?;}Ok(())})?;}
 for value in values{control.step()?;rows=rows.checked_add(list(record(value)?,4)?.len()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native row count overflow"))?;check(rows)?;}Ok(())})?;
 reconstruct(Snapshot::__dsl_from_record_controlled(source,control)?,control)
}

pub(crate)fn record_controlled(source:&PlySnapshot,control:&mut semio_framework_value::NativeEncodeControl<'_>,maximum_rows:usize)->Result<semio_framework_dsl_record::RecordValue,ValueError>{
 fn project(source:&PlySnapshot,control:&mut semio_framework_value::NativeEncodeControl<'_>,maximum_rows:usize)->Result<Snapshot,ValueError>{
  fn add(rows:&mut usize,count:usize,maximum:usize)->Result<(),ValueError>{*rows=rows.checked_add(count).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native row count overflow"))?;if *rows>maximum{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::OwnershipLimit,"PLY native row limit exceeded"))}Ok(())}
  fn reserve(frontier:&mut Vec<&PlyValue>,count:usize,control:&mut semio_framework_value::NativeEncodeControl<'_>)->Result<(),ValueError>{control.charge(count.checked_mul(std::mem::size_of::<&PlyValue>()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native frontier overflow"))?)?;frontier.try_reserve_exact(count).map_err(|_|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::AllocationFailed,"PLY native frontier allocation failed"))}
  let mut rows=1usize;let mut roots=0usize;if rows>maximum_rows{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::OwnershipLimit,"PLY native row limit exceeded"))}add(&mut rows,source.comments.len(),maximum_rows)?;add(&mut rows,source.elements.len(),maximum_rows)?;
  control.begin_stage(source.elements.len())?;for element in&source.elements{control.step()?;add(&mut rows,element.properties.len(),maximum_rows)?;add(&mut rows,element.rows.len(),maximum_rows)?;control.scoped_stage(|control|{control.begin_stage(element.rows.len())?;for row in&element.rows{control.step()?;roots=roots.checked_add(row.values.len()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native root count overflow"))?;add(&mut rows,row.values.len().checked_mul(2).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native cell count overflow"))?,maximum_rows)?;}Ok::<(),ValueError>(())})?;}
  let mut frontier=control.allocate_vec::<&PlyValue>(roots)?;for element in&source.elements{control.scoped_stage(|control|{control.begin_stage(element.rows.len())?;for row in&element.rows{control.step()?;control.scoped_stage(|control|{control.begin_stage(row.values.len())?;for value in&row.values{frontier.push(value);control.step()?;}Ok::<(),ValueError>(())})?;}Ok::<(),ValueError>(())})?;}
  control.begin_stage(0)?;let mut position=0;while position<frontier.len(){control.step()?;if let PlyValue::List(children)=frontier[position]{add(&mut rows,children.len().checked_mul(2).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native list count overflow"))?,maximum_rows)?;reserve(&mut frontier,children.len(),control)?;for value in children{frontier.push(value);control.step()?;}}position+=1;}
  control.begin_stage(frontier.len())?;let mut values=control.allocate_vec::<Value>(frontier.len())?;let mut next=u64::try_from(roots).map_err(|_|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native root index overflow"))?;
  for value in frontier{
   let(kind,integer_value,float32_ieee754_bits,float64_ieee754_bits)=match value{
    PlyValue::Char(value)=>("char",Some(i64::from(*value)),None,None),PlyValue::UChar(value)=>("uchar",Some(i64::from(*value)),None,None),PlyValue::Short(value)=>("short",Some(i64::from(*value)),None,None),PlyValue::UShort(value)=>("ushort",Some(i64::from(*value)),None,None),PlyValue::Int(value)=>("int",Some(i64::from(*value)),None,None),PlyValue::UInt(value)=>("uint",Some(i64::from(*value)),None,None),PlyValue::Float(value)=>("float",None,Some(value.to_bits()),None),PlyValue::Double(value)=>("double",None,None,Some(value.to_bits())),PlyValue::List(_)=>("list",None,None,None),
   };let mut list_values=match value{PlyValue::List(children)=>control.allocate_vec::<u64>(children.len())?,_=>control.allocate_vec::<u64>(0)?};
   if let PlyValue::List(children)=value{control.scoped_stage(|control|{control.begin_stage(children.len())?;for _ in children{list_values.push(next);next=next.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native child index overflow"))?;control.step()?;}Ok::<(),ValueError>(())})?;}
   values.push(Value{kind:control.copy_text(kind)?,integer_value,float32_ieee754_bits,float64_ieee754_bits,list_values});control.step()?;
  }
  control.begin_stage(source.elements.len())?;let mut elements=control.allocate_vec::<Element>(source.elements.len())?;let mut root=0u64;
  for element in&source.elements{
   let mut properties=control.allocate_vec::<Property>(element.properties.len())?;control.scoped_stage(|control|{control.begin_stage(element.properties.len())?;for property in&element.properties{
    let value=match property{
     PlyProperty::Scalar{name,kind}=>Property{name:control.copy_text(name)?,form:control.copy_text("scalar")?,scalar_kind:Some(control.copy_text(scalar_name(*kind))?),count_kind:None,value_kind:None},
     PlyProperty::List{name,count_kind,value_kind}=>Property{name:control.copy_text(name)?,form:control.copy_text("list")?,scalar_kind:None,count_kind:Some(control.copy_text(scalar_name(*count_kind))?),value_kind:Some(control.copy_text(scalar_name(*value_kind))?)},
    };properties.push(value);control.step()?;
   }Ok::<(),ValueError>(())})?;
   let mut occurrences=control.allocate_vec::<Row>(element.rows.len())?;control.scoped_stage(|control|{control.begin_stage(element.rows.len())?;for row in&element.rows{let mut values=control.allocate_vec::<u64>(row.values.len())?;control.scoped_stage(|control|{control.begin_stage(row.values.len())?;for _ in&row.values{values.push(root);root=root.checked_add(1).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"PLY native cell index overflow"))?;control.step()?;}Ok::<(),ValueError>(())})?;occurrences.push(Row{values});control.step()?;}Ok::<(),ValueError>(())})?;
   elements.push(Element{name:control.copy_text(&element.name)?,count:element.count,properties,rows:occurrences});control.step()?;
  }
  control.begin_stage(source.comments.len())?;let mut comments=control.allocate_vec::<String>(source.comments.len())?;for comment in&source.comments{comments.push(control.copy_text(comment)?);control.step()?;}
  let snapshot=Snapshot{schema:control.copy_text(&source.schema)?,format:control.copy_text(match source.format{PlyFormat::Ascii=>"ascii",PlyFormat::BinaryLittleEndian=>"binaryLittleEndian",PlyFormat::BinaryBigEndian=>"binaryBigEndian"})?,comments,elements,values};Ok(snapshot)
 }
 let snapshot=project(source,control,maximum_rows)?;snapshot.__dsl_to_record_controlled(control)
}
